import json
import os
import subprocess
import sys
import tempfile
import unittest

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CITATION_GUARD = os.path.join(ROOT_DIR, "src", "scripts", "citation-guard.py")
WRITE_REPORT = os.path.join(ROOT_DIR, "src", "scripts", "write-proof-report.py")


def run_script(script, *args):
    return subprocess.run(
        [sys.executable, script, *args],
        capture_output=True,
        text=True,
        timeout=30,
    )


def make_change(**overrides):
    change = {
        "stage": "mechanical",
        "line": 1,
        "type": "typo",
        "level": "word",
        "before": "המחשבה",
        "after": "המחשבה",
        "rationale": "doubled letter",
        "meaningRisk": "low",
    }
    change.update(overrides)
    return change


class TestCitationGuard(unittest.TestCase):
    def _run(self, changes_payload, proof_base_text):
        with tempfile.TemporaryDirectory() as tmpdir:
            changes_path = os.path.join(tmpdir, "changes.json")
            proof_base_path = os.path.join(tmpdir, "proof_base.md")
            with open(changes_path, "w", encoding="utf-8") as fh:
                json.dump(changes_payload, fh, ensure_ascii=False)
            with open(proof_base_path, "w", encoding="utf-8") as fh:
                fh.write(proof_base_text)
            proc = run_script(
                CITATION_GUARD,
                "--changes",
                changes_path,
                "--proof-base",
                proof_base_path,
                "--json",
            )
        self.assertEqual(proc.returncode, 0, proc.stderr)
        return json.loads(proc.stdout)

    def test_downgrades_change_overlapping_footnote_marker(self):
        change = make_change(
            line=1,
            before="ראה לעיל[^3] ",
            after="ראה לעיל [^3] ",
            rationale="missing space before footnote",
        )
        proof_base = "ראה לעיל[^3] לעניין זה.\n"
        result = self._run({"stage": "mechanical", "changes": [change]}, proof_base)
        out = result["changes"][0]
        self.assertFalse(out["applied"])
        self.assertEqual(out["skipReason"], "citation-guard")

    def test_leaves_clean_prose_change_untouched(self):
        change = make_change(
            line=1,
            before="המחשבה",
            after="המחשבה",
            rationale="doubled letter",
        )
        proof_base = "זוהי המחשבה המרכזית של המאמר.\n"
        result = self._run({"stage": "mechanical", "changes": [change]}, proof_base)
        out = result["changes"][0]
        # Untouched: no applied/skipReason keys added by the guard.
        self.assertNotIn("applied", out)
        self.assertNotIn("skipReason", out)
        self.assertEqual(out["before"], "המחשבה")
        self.assertEqual(out["rationale"], "doubled letter")

    def test_nfc_insensitive_matching(self):
        # Compose the before/after strings and the PROOF_BASE line with
        # decomposed (NFD) Hebrew + a footnote marker, to prove the guard
        # normalizes before matching rather than relying on raw code points.
        import unicodedata

        raw = 'ראה "ציטוט מודגש" לעיל'
        nfd_before = unicodedata.normalize("NFD", raw)
        change = make_change(line=1, before=nfd_before, after=nfd_before, rationale="quote spacing")
        proof_base_line = unicodedata.normalize("NFD", raw) + "\n"
        result = self._run({"stage": "mechanical", "changes": [change]}, proof_base_line)
        out = result["changes"][0]
        self.assertFalse(out["applied"])
        self.assertEqual(out["skipReason"], "citation-guard")

    def test_no_match_change_is_kept_not_dropped(self):
        # `before` does not appear anywhere on the given line, and contains
        # no citation/quotation token itself -- the guard must not drop it.
        change = make_change(
            line=1,
            before="טקסט שאינו קיים בשורה",
            after="טקסט מתוקן",
            rationale="placeholder edit",
        )
        proof_base = "שורה שונה לגמרי שאינה מכילה את הטקסט המקורי.\n"
        result = self._run({"stage": "mechanical", "changes": [change]}, proof_base)
        self.assertEqual(len(result["changes"]), 1)
        out = result["changes"][0]
        self.assertNotIn("applied", out)
        self.assertEqual(out["before"], "טקסט שאינו קיים בשורה")

    def test_accepts_bare_array_payload(self):
        change = make_change(line=1, before="שלום", after="שלום עולם", rationale="add word")
        with tempfile.TemporaryDirectory() as tmpdir:
            changes_path = os.path.join(tmpdir, "changes.json")
            proof_base_path = os.path.join(tmpdir, "proof_base.md")
            with open(changes_path, "w", encoding="utf-8") as fh:
                json.dump([change], fh, ensure_ascii=False)
            with open(proof_base_path, "w", encoding="utf-8") as fh:
                fh.write("שלום.\n")
            proc = run_script(
                CITATION_GUARD, "--changes", changes_path, "--proof-base", proof_base_path
            )
        self.assertEqual(proc.returncode, 0, proc.stderr)
        result = json.loads(proc.stdout)
        self.assertIsInstance(result, list)
        self.assertEqual(len(result), 1)

    def test_english_parenthetical_citation_overlap(self):
        change = make_change(
            stage="mechanical",
            line=1,
            before="(Author 2019 p. 45)",
            after="(Author, 2019, p. 45)",
            rationale="missing commas in citation",
        )
        proof_base = "As argued elsewhere (Author 2019 p. 45) this holds.\n"
        result = self._run({"stage": "mechanical", "changes": [change]}, proof_base)
        out = result["changes"][0]
        self.assertFalse(out["applied"])
        self.assertEqual(out["skipReason"], "citation-guard")


class TestWriteProofReport(unittest.TestCase):
    def _run(self, data, extra_args=()):
        with tempfile.TemporaryDirectory() as tmpdir:
            input_path = os.path.join(tmpdir, "input.json")
            out_path = os.path.join(tmpdir, "report.md")
            with open(input_path, "w", encoding="utf-8") as fh:
                json.dump(data, fh, ensure_ascii=False)
            proc = run_script(
                WRITE_REPORT, "--input", input_path, "--out", out_path, *extra_args
            )
            rendered = None
            if os.path.exists(out_path):
                with open(out_path, encoding="utf-8") as fh:
                    rendered = fh.read()
        return proc, rendered

    def test_gates_table_renders_skipped_stage_with_reason(self):
        data = {
            "filebase": "sample-article",
            "source": "articles/sample-article.md",
            "correctedCopy": "articles/sample-article.proofed.md",
            "language": "he",
            "profile": "none",
            "date": "2026-09-02",
            "gates": [
                {
                    "stage": "editorial",
                    "ran": True,
                    "why": "venue profile present",
                    "model": "opus",
                    "rounds": 1,
                    "outcome": "5 findings",
                },
                {
                    "stage": "mechanical",
                    "ran": False,
                    "why": "no spell-checker available on this machine",
                    "model": None,
                    "rounds": None,
                    "outcome": "skipped",
                },
            ],
            "memo": "The article leans journalistic in §2.",
            "changes": [],
        }
        proc, rendered = self._run(data)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertIn("mechanical", rendered)
        self.assertIn("no (skipped)", rendered)
        self.assertIn("no spell-checker available on this machine", rendered)
        self.assertIn("editorial", rendered)
        self.assertIn("yes", rendered)

    def test_empty_change_list_is_clean_pass_with_no_applied_changes(self):
        # VER-08 negative case.
        data = {
            "filebase": "clean-article",
            "source": "articles/clean-article.md",
            "correctedCopy": "articles/clean-article.proofed.md",
            "language": "en",
            "profile": "loaded",
            "date": "2026-09-02",
            "gates": [
                {"stage": "mechanical", "ran": True, "why": "ran normally", "model": "sonnet", "rounds": 1, "outcome": "clean"}
            ],
            "memo": None,
            "changes": [],
        }
        proc, rendered = self._run(data)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertIn("clean pass", rendered.lower())
        self.assertIn("No changes were applied", rendered)
        self.assertIn("Applied: 0 total", rendered)
        self.assertIn("_No flags._", rendered)

    def test_applied_and_flagged_changes_render_in_correct_sections(self):
        applied_change = make_change(
            stage="mechanical",
            line=12,
            before="שלום",
            after="שלום.",
            rationale="missing period",
        )
        applied_change["applied"] = True

        flagged_change = make_change(
            stage="mechanical",
            line=20,
            before="[^2]",
            after="[^2].",
            rationale="touches a footnote marker",
        )
        flagged_change["applied"] = False
        flagged_change["skipReason"] = "citation-guard"

        data = {
            "filebase": "mixed-article",
            "source": "articles/mixed-article.md",
            "correctedCopy": "articles/mixed-article.proofed.md",
            "language": "he",
            "profile": "loaded",
            "date": "2026-09-02",
            "gates": [
                {"stage": "mechanical", "ran": True, "why": "ran normally", "model": "sonnet", "rounds": 1, "outcome": "1 applied, 1 flagged"}
            ],
            "memo": None,
            "changes": [applied_change, flagged_change],
        }
        proc, rendered = self._run(data)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertIn("Applied: 1 total", rendered)
        self.assertIn("Flagged (not applied): 1", rendered)
        self.assertIn("missing period", rendered)
        self.assertIn("citation-guard", rendered)
        self.assertIn("touches a footnote marker", rendered)
        # Applied changes table must not list the flagged one, and vice versa.
        applied_section, _, flags_section = rendered.partition("## Flags and notes")
        self.assertIn("missing period", applied_section)
        self.assertNotIn("touches a footnote marker", applied_section)
        self.assertIn("touches a footnote marker", flags_section)

    def test_json_summary_emitted_when_out_given(self):
        data = {
            "filebase": "summary-article",
            "source": "articles/summary-article.md",
            "correctedCopy": "articles/summary-article.proofed.md",
            "language": "en",
            "profile": "none",
            "date": "2026-09-02",
            "gates": [],
            "memo": None,
            "changes": [],
        }
        proc, _ = self._run(data)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        summary = json.loads(proc.stdout.strip().splitlines()[-1])
        self.assertTrue(summary["cleanPass"])
        self.assertEqual(summary["appliedCount"], 0)
        self.assertEqual(summary["flaggedCount"], 0)
        self.assertIsNotNone(summary["written"])


if __name__ == "__main__":
    unittest.main()
